1	package world
2	
3	import "errors"
4	
5	// RecoveryPreview 是一次恢复预览的结果。
6	//
7	// 预览只读：返回槽当前指向的记录标识、按本槽保存生效次序选中的来源记录
8	// 标识，以及来源记录的完整世界状态（深拷贝）。它不改变槽指向、历史或
9	// 任何记录文件。
10	type RecoveryPreview struct {
11		// Current 是槽指针当前指向的记录标识。它可能已损坏或被删除，
12		// 但仍是之后确认恢复时必须一致的“当前标识”。
13		Current RecordID
14		// Source 是选中的来源记录标识：本槽保存次序最近一份校验通过且
15		// 版本可接受的记录。它可能与 Current 相同（当前记录本就可读）。
16		Source RecordID
17		// State 是来源记录保存时的完整世界状态（深拷贝，修改不影响存档）。
18		State State
19	}
20	
21	// PreviewRecovery 预览将恢复的内容而不改写存档。
22	//
23	// 传入槽名与调用方可接受的规则版本集合，返回槽当前指向的记录标识、选中
24	// 的来源记录标识及其完整世界状态。来源按本槽“保存生效次序”选择最近一份
25	// 格式受支持、内容与父关系校验通过且版本可接受的记录，越过缺失、截断、
26	// 格式版本不受支持、校验失败与版本不被接受的记录；分支只在分支自身的
27	// 历史中选择，不跨入来源槽。当前记录本就完好且版本可接受时可以选中它本身。
28	//
29	// 槽不存在返回 *NotFoundError；槽指针无法解析返回 *CorruptError（即使其
30	// 指向的记录已损坏或被删除，也仍会返回该当前标识用于预览）；槽中没有
31	// 任何可用记录时返回包装了 ErrUnrecoverable 的 *UnrecoverableError。
32	// 预览绝不写入、修补或删除任何数据，可重复调用。
33	func (a *Archive) PreviewRecovery(slot string, acceptedVersions []string) (RecoveryPreview, error) {
34		if !validSlotName(slot) {
35			return RecoveryPreview{}, &NotFoundError{Slot: slot}
36		}
37		lock, err := acquireSharedLock(a.dir)
38		if err != nil {
39			return RecoveryPreview{}, err
40		}
41		defer lock.release()
42		return a.previewRecoveryLocked(slot, acceptedVersions)
43	}
44	
45	// previewRecoveryLocked 在调用方已持锁（共享或排他均可）的前提下执行预览。
46	func (a *Archive) previewRecoveryLocked(slot string, acceptedVersions []string) (RecoveryPreview, error) {
47		pointer, err := a.readSlotPointerLocked(slot)
48		if err != nil {
49			return RecoveryPreview{}, err
50		}
51		// slotHistoryLocked 以指针当前指向为链头，并负责旧格式裸指针沿可信
52		// 父链的重建；当前记录损坏或缺失只会让重建停在那里，不妨碍指针内嵌
53		// 历史索引中更早的本槽记录成为候选。
54		history, err := a.slotHistoryLocked(slot)
55		if err != nil {
56			return RecoveryPreview{}, err
57		}
58		env, err := a.firstRecoverableLocked(history, acceptedVersions)
59		if err != nil {
60			var ue *UnrecoverableError
61			if errors.As(err, &ue) {
62				ue.Slot = slot
63			}
64			return RecoveryPreview{}, err
65		}
66		return RecoveryPreview{
67			Current: pointer.Latest,
68			Source:  env.ID,
69			State:   cloneState(env.State),
70		}, nil
71	}
72	
73	// ConfirmRecovery 把预览选中的来源记录正式保存回本槽并继续使用。
74	//
75	// 入参为槽名、预览返回的当前记录标识 current 与来源记录标识 source，以及
76	// 调用方可接受的规则版本集合。确认在排他锁下重新判断全部前提，绝不使用
77	// 调用方可能修改过的预览状态，而是重新读取并校验来源记录：
78	//
79	//   - current 或 source 为空，或槽已不再指向 current（被并发覆盖、升级
80	//     或另一次恢复抢先提交），返回 *ConflictError。比较只针对槽所指记录，
81	//     即使它已损坏或被删除也不例外，因此损坏/删除的当前标识不会妨碍从
82	//     本槽完好旧记录恢复。
83	//   - 来源必须仍属于该槽、格式受支持、仍能通过内容与父关系校验且版本
84	//     可接受。其他槽
85	//     的记录、未生效的残留/孤儿记录按 *NotFoundError 拒绝；来源后来被
86	//     删除返回 *NotFoundError，损坏（截断、格式版本不受支持、校验失败、
87	//     父关系断裂）返回
88	//     *CorruptError，版本不再被接受返回 *VersionRejectedError。来源失效
89	//     时不改选其他记录。
90	//
91	// 成功后产生一条独立的新记录（即使来源就是当前记录），槽指向新记录，
92	// 新记录以来源为父，种子、完整规则、时间片、角色及物品的内容和排列原样
93	// 复制，允许时间片回到来源时刻。旧历史按原保存次序保留，新记录排在最
94	// 前；来源之后仍完好的旧记录可照常读取或分支，已存在的分支不受影响。
95	// 同一 current 上的并发确认、以及确认与普通覆盖或规则升级竞争时，最多
96	// 一个成功。
97	func (a *Archive) ConfirmRecovery(slot string, current, source RecordID, acceptedVersions []string) (RecordInfo, error) {
98		if !validSlotName(slot) {
99			return RecordInfo{}, &NotFoundError{Slot: slot}
100		}
101		if current == "" || source == "" {
102			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "确认恢复必须提供当前记录标识与来源记录标识"}
103		}
104	
105		lock, err := acquireLock(a.dir)
106		if err != nil {
107			return RecordInfo{}, err
108		}
109		defer lock.release()
110	
111		oldPointer, err := a.readSlotPointerLocked(slot)
112		if err != nil {
113			return RecordInfo{}, err
114		}
115		// 乐观并发控制：只有槽仍指向预览时的当前记录才允许确认。当前记录
116		// 本身可能已损坏或被删除——那正是需要恢复的情形——故这里只比较标识，
117		// 不读取它。
118		if oldPointer.Latest != current {
119			return RecordInfo{}, &ConflictError{
120				Slot:   slot,
121				Reason: "槽当前记录已改变，请重新预览后再确认",
122			}
123		}
124	
125		// 来源必须仍在本槽保存次序内：其他槽记录与未生效的孤儿/残留记录
126		// 都不在其中，按记录不存在拒绝。
127		history, err := a.slotHistoryLocked(slot)
128		if err != nil {
129			return RecordInfo{}, err
130		}
131		if err := assertRecordInOrder(history, source); err != nil {
132			return RecordInfo{}, &NotFoundError{Slot: slot, Record: source}
133		}
134	
135		// 重新读取并完整校验来源，不采信调用方带回的任何状态。
136		env, err := a.loadAndVerifyLocked(source)
137		if err != nil {
138			if ce, ok := err.(*CorruptError); ok {
139				ce.Slot = slot
140			}
141			return RecordInfo{}, err
142		}
143		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
144			return RecordInfo{}, &VersionRejectedError{
145				Slot:     slot,
146				Record:   source,
147				Version:  env.State.Rules.Version,
148				Accepted: append([]string(nil), acceptedVersions...),
149			}
150		}
151	
152		// 以选中的来源为父（即使来源就是当前记录，仍保存一条独立新记录），
153		// 种子、完整规则、时间片、角色及物品的内容和排列原样复制，允许时间
154		// 片回到来源时刻。历史承接点用槽指针的当前指向：当前记录已损坏或被
155		// 删除时不能去校验它，但来源之后已经生效的本槽历史仍要原样保留，不
156		// 沿来源的父链截断。沿用共同的组装、落盘与槽指针提交路径。
157		return a.appendSlotRecordLocked(slotSave{
158			slot:          slot,
159			oldPointer:    oldPointer,
160			parent:        source,
161			historyAnchor: oldPointer.Latest,
162			state:         cloneState(env.State),
163		})
164	}
165	
166	// assertRecordInOrder 确认 id 出现在按保存生效次序排列的标识序列中。
167	func assertRecordInOrder(order []RecordID, id RecordID) error {
168		for _, cid := range order {
169			if cid == id {
170				return nil
171			}
172		}
173		return &NotFoundError{Record: id}
174	}
