1	package world
2	
3	import (
4		"errors"
5		"math"
6		"math/big"
7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// noLimitRules 是不设携带上限、含两个地点与两种物品的规则。
13	func noLimitRules() Rules {
14		return Rules{
15			Version:   "v1",
16			Locations: []string{"hall", "yard"},
17			Edges:     []Edge{{From: "hall", To: "yard"}},
18			ItemKinds: []string{"gold", "key"},
19		}
20	}
21	
22	func mustRuleError(t *testing.T, err error, substrs ...string) {
23		t.Helper()
24		var re *RuleError
25		if !errors.As(err, &re) {
26			t.Fatalf("应返回 *RuleError，得到 %T: %v", err, err)
27		}
28		for _, s := range substrs {
29			if !strings.Contains(re.Reason, s) {
30				t.Fatalf("错误信息应包含 %q: %v", s, re)
31			}
32		}
33	}
34	
35	// 同一角色同一物品的增减与原始数量合并后判断：1 + MaxInt + MinInt = 0，
36	// 且与条目次序无关。
37	func TestApplyMergesDeltasExactly(t *testing.T) {
38		deltas := [][]ItemChange{
39			{{Character: "hero", Item: "gold", Delta: math.MaxInt}, {Character: "hero", Item: "gold", Delta: math.MinInt}},
40			{{Character: "hero", Item: "gold", Delta: math.MinInt}, {Character: "hero", Item: "gold", Delta: math.MaxInt}},
41		}
42		for _, d := range deltas {
43			w, err := NewWorld(InitialData{
44				Seed:  1,
45				Rules: noLimitRules(),
46				Characters: []Character{
47					{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
48				},
49			})
50			if err != nil {
51				t.Fatalf("NewWorld: %v", err)
52			}
53			st, err := w.Apply(Commit{ItemChanges: d, Time: 1})
54			if err != nil {
55				t.Fatalf("合并后结果为 0 应成功: %v", err)
