package world

import (
	"fmt"
	"unicode/utf8"
)

// RuleError 表示数据或提交违反了世界规则。
type RuleError struct {
	Reason string
}

func (e *RuleError) Error() string { return "world: " + e.Reason }

func ruleErrorf(format string, args ...any) error {
	return &RuleError{Reason: fmt.Sprintf(format, args...)}
}

// validateRules 校验规则本身：非空版本、地点不重复且非空标识、
// 连通关系只引用已有地点、物品不重复、携带上限非负。
//
// 全部文本标识（版本、地点、道路端点、物品种类、携带上限的角色键）还
// 必须是合法 UTF-8：含无效字节的字符串经 JSON 保存会被悄悄改写成替换
// 字符，可能使不同标识重名，因此必须在接纳世界数据时拒绝，即使该地点、
// 物品或上限键暂时无人使用。
func validateRules(r Rules) error {
	if !utf8.ValidString(r.Version) {
		return ruleErrorf("规则版本不是合法 UTF-8: %q", r.Version)
	}
	if r.Version == "" {
		return ruleErrorf("规则版本不能为空")
	}
	locs := make(map[string]struct{}, len(r.Locations))
	for i, l := range r.Locations {
		if !utf8.ValidString(l) {
			return ruleErrorf("第 %d 个地点标识不是合法 UTF-8: %q", i, l)
		}
		if l == "" {
			return ruleErrorf("地点标识不能为空")
		}
		if _, ok := locs[l]; ok {
			return ruleErrorf("地点标识重复: %q", l)
		}
		locs[l] = struct{}{}
	}
	for i, e := range r.Edges {
		if !utf8.ValidString(e.From) {
			return ruleErrorf("连通关系 %d 的起点不是合法 UTF-8: %q", i, e.From)
		}
		if !utf8.ValidString(e.To) {
			return ruleErrorf("连通关系 %d 的终点不是合法 UTF-8: %q", i, e.To)
		}
		if _, ok := locs[e.From]; !ok {
			return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.From)
		}
		if _, ok := locs[e.To]; !ok {
			return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.To)
		}
	}
	kinds := make(map[string]struct{}, len(r.ItemKinds))
	for i, k := range r.ItemKinds {
		if !utf8.ValidString(k) {
			return ruleErrorf("第 %d 个物品种类标识不是合法 UTF-8: %q", i, k)
		}
		if k == "" {
			return ruleErrorf("物品种类标识不能为空")
		}
		if _, ok := kinds[k]; ok {
			return ruleErrorf("物品种类重复: %q", k)
		}
		kinds[k] = struct{}{}
	}
	for who, limit := range r.CarryLimits {
		if !utf8.ValidString(who) {
			return ruleErrorf("携带上限的角色键不是合法 UTF-8: %q", who)
		}
		if limit < 0 {
			return ruleErrorf("角色 %q 的携带上限不能为负: %d", who, limit)
		}
	}
	return nil
}

func (r Rules) adjacent(from, to string) bool {
	for _, e := range r.Edges {
		if (e.From == from && e.To == to) || (e.From == to && e.To == from) {
			return true
		}
	}
	return false
}

// validateCharacters 校验角色集合：标识不重复、位于已有地点；
// 物品种类合法、数量非负、不重复，总量不超过携带上限。
func validateCharacters(chars []Character, r Rules) error {
	locSet := make(map[string]struct{}, len(r.Locations))
	for _, l := range r.Locations {
		locSet[l] = struct{}{}
	}
	kindSet := make(map[string]struct{}, len(r.ItemKinds))
	for _, k := range r.ItemKinds {
		kindSet[k] = struct{}{}
	}
	ids := make(map[string]struct{}, len(chars))
	for _, c := range chars {
		if c.ID == "" {
			return ruleErrorf("角色标识不能为空")
		}
		if _, ok := ids[c.ID]; ok {
			return ruleErrorf("角色标识重复: %q", c.ID)
		}
		ids[c.ID] = struct{}{}
		if _, ok := locSet[c.Location]; !ok {
			return ruleErrorf("角色 %q 位于不存在的地点: %q", c.ID, c.Location)
		}
		seen := make(map[string]struct{}, len(c.Items))
		for _, it := range c.Items {
			if _, ok := kindSet[it.Item]; !ok {
				return ruleErrorf("角色 %q 持有规则不允许的物品: %q", c.ID, it.Item)
			}
			if _, dup := seen[it.Item]; dup {
				return ruleErrorf("角色 %q 的物品 %q 重复列出", c.ID, it.Item)
			}
			seen[it.Item] = struct{}{}
			if it.Count < 0 {
				return ruleErrorf("角色 %q 的物品 %q 数量不能为负: %d", c.ID, it.Item, it.Count)
			}
		}
		// 携带上限按真实总量判断，规则与建立世界、提交物品变化共用同一口径：
		// 精确求和不因回绕放过超限；未设上限的角色不检查总量，其总量允许
		// 超过 int 最大值。
		if err := carryLimitError(c.ID, c.Items, r.CarryLimits); err != nil {
			return err
		}
	}
	return nil
}

// validateInitialData 校验建立世界的初始数据。
func validateInitialData(d InitialData) error {
	if err := validateRules(d.Rules); err != nil {
		return err
	}
	if err := validateCharacters(d.Characters, d.Rules); err != nil {
		return err
	}
	return nil
}

package world

import "sort"

// maxGenerateLocations 是生成地图允许的最大地点数量。
const maxGenerateLocations = 256

// GenerateRequest 是按种子生成地图并建立世界的请求。
//
// Seed 是整数地图种子，支持完整的 int64 范围（含零和负数）。Locations
// 是地图地点；Required 是必有道路，Banned 是禁用道路，RoadCount 是
// 生成后不同道路的总数。道路无向：同一道路重复出现或反向列出只算一条。
// RulesVersion、ItemKinds、CarryLimits 与 Characters 与 NewWorld 的
// 对应输入含义相同，它们不参与地图生成，改变它们不影响生成的地图。
type GenerateRequest struct {
	// Seed 是整数地图种子。
	Seed int64
	// Locations 是地图地点，1 至 256 个，标识非空且不重复。
	Locations []string
	// Required 是必须包含的道路，可以成环。
	Required []Edge
	// Banned 是必须避开的道路。
	Banned []Edge
	// RoadCount 是生成后不同道路的总数。
	RoadCount int
	// RulesVersion 是规则版本。
	RulesVersion string
	// ItemKinds 是允许出现的物品种类。
	ItemKinds []string
	// CarryLimits 给出每个角色可携带物品的总量上限。
	CarryLimits map[string]int
	// Characters 是初始角色集合。
	Characters []Character
}

// GenerateWorld 按种子生成地图并建立世界。生成的地图是无向道路图：
// 包含全部必有道路、避开全部禁用道路、任意两个地点之间都能沿道路到达，
// 且不同道路的数量严格等于请求的目标数量；同一道路只保留一条，输出中
// 道路方向与排列是规范的（端点按字典序、道路按端点排序）。
//
// 同一种子和同一组地图约束生成的地点与道路内容、方向表示和排列完全
// 一致，与调用先后、是否生成过其他世界及进程是否重启无关；地点与两类
// 道路的输入次序、重复道路或正反写法不影响结果。存在多种合法地图时，
// 不同种子可以产生不同道路组合。约束不合法（地点数量越界、标识为空或
// 重复、道路引用未知地点或连接自身、同一道路同时必有和禁用、目标数量
// 为负、小于必有道路数、少于连通全图所需数量、超过可用道路数，或禁用
// 道路使地图无法连通）时返回 *RuleError，不会产生可用世界；约束有解时
// 每个种子都能成功生成。
//
// 生成不修改调用方输入；规则版本、角色、物品种类与携带上限按输入保留，
// 时间片从零开始。除此之外与 NewWorld 行为一致。
func GenerateWorld(req GenerateRequest) (*World, error) {
	locs, edges, err := generateMap(req.Seed, req.Locations, req.Required, req.Banned, req.RoadCount)
	if err != nil {
		return nil, err
	}
	return NewWorld(InitialData{
		Seed: req.Seed,
		Rules: Rules{
			Version:     req.RulesVersion,
			Locations:   locs,
			Edges:       edges,
			ItemKinds:   req.ItemKinds,
			CarryLimits: req.CarryLimits,
		},
		Characters: req.Characters,
	})
}

// canonicalEdge 把一条无向道路规范为端点字典序较小的在前。
func canonicalEdge(e Edge) Edge {
	if e.To < e.From {
		return Edge{From: e.To, To: e.From}
	}
	return e
}

// generateMap 按种子与地图约束生成规范的地点列表和道路列表。
// 输入切片不会被修改。
func generateMap(seed int64, locations []string, required, banned []Edge, roadCount int) ([]string, []Edge, error) {
	n := len(locations)
	if n < 1 || n > maxGenerateLocations {
		return nil, nil, ruleErrorf("地点数量必须在 1 到 %d 之间: %d", maxGenerateLocations, n)
	}
	locs := append([]string(nil), locations...)
	sort.Strings(locs)
	locSet := make(map[string]struct{}, n)
	for _, l := range locs {
		if l == "" {
			return nil, nil, ruleErrorf("地点标识不能为空")
		}
		if _, ok := locSet[l]; ok {
			return nil, nil, ruleErrorf("地点标识重复: %q", l)
		}
		locSet[l] = struct{}{}
	}

