package world

import (
	"sort"
	"unicode/utf8"
)

// maxGenerateLocations 是生成地图允许的最大地点数量。
const maxGenerateLocations = 256

// GenerateRequest 是按种子生成地图并建立世界的请求。
//
// Seed 是整数地图种子，支持完整的 int64 范围（含零和负数）。Locations
// 是地图地点；Required 是必有道路，Banned 是禁用道路，RoadCount 是
// 生成后不同道路的总数。道路无向：同一道路重复出现或反向列出只算一条。
// RulesVersion、ItemKinds、CarryLimits 与 Characters 与 NewWorld 的
// 对应输入含义相同，它们不参与地图生成，改变它们不影响生成的地图。
type GenerateRequest struct {
	// Seed 是整数地图种子。
	Seed int64
	// Locations 是地图地点，1 至 256 个，标识非空且不重复。
	Locations []string
	// Required 是必须包含的道路，可以成环。
	Required []Edge
	// Banned 是必须避开的道路。
	Banned []Edge
	// RoadCount 是生成后不同道路的总数。
	RoadCount int
	// RulesVersion 是规则版本。
	RulesVersion string
	// ItemKinds 是允许出现的物品种类。
	ItemKinds []string
	// CarryLimits 给出每个角色可携带物品的总量上限。
	CarryLimits map[string]int
	// Characters 是初始角色集合。
	Characters []Character
}

// GenerateWorld 按种子生成地图并建立世界。生成的地图是无向道路图：
// 包含全部必有道路、避开全部禁用道路、任意两个地点之间都能沿道路到达，
// 且不同道路的数量严格等于请求的目标数量；同一道路只保留一条，输出中
// 道路方向与排列是规范的（端点按字典序、道路按端点排序）。
//
// 同一种子和同一组地图约束生成的地点与道路内容、方向表示和排列完全
// 一致，与调用先后、是否生成过其他世界及进程是否重启无关；地点与两类
// 道路的输入次序、重复道路或正反写法不影响结果。存在多种合法地图时，
// 不同种子可以产生不同道路组合。约束不合法（地点数量越界、标识为空或
// 重复、道路引用未知地点或连接自身、同一道路同时必有和禁用、目标数量
// 为负、小于必有道路数、少于连通全图所需数量、超过可用道路数，或禁用
// 道路使地图无法连通）时返回 *RuleError，不会产生可用世界；约束有解时
// 每个种子都能成功生成。
//
// 生成不修改调用方输入；规则版本、角色、物品种类与携带上限按输入保留，
// 时间片从零开始。除此之外与 NewWorld 行为一致。
func GenerateWorld(req GenerateRequest) (*World, error) {
	locs, edges, err := generateMap(req.Seed, req.Locations, req.Required, req.Banned, req.RoadCount)
	if err != nil {
		return nil, err
	}
	return NewWorld(InitialData{
		Seed: req.Seed,
		Rules: Rules{
			Version:     req.RulesVersion,
			Locations:   locs,
			Edges:       edges,
			ItemKinds:   req.ItemKinds,
			CarryLimits: req.CarryLimits,
		},
		Characters: req.Characters,
	})
}

// canonicalEdge 把一条无向道路规范为端点字典序较小的在前。
func canonicalEdge(e Edge) Edge {
	if e.To < e.From {
		return Edge{From: e.To, To: e.From}
	}
	return e
}

// generateMap 按种子与地图约束生成规范的地点列表和道路列表。
// 输入切片不会被修改。
func generateMap(seed int64, locations []string, required, banned []Edge, roadCount int) ([]string, []Edge, error) {
	n := len(locations)
	if n < 1 || n > maxGenerateLocations {
		return nil, nil, ruleErrorf("地点数量必须在 1 到 %d 之间: %d", maxGenerateLocations, n)
	}
	locs := append([]string(nil), locations...)
	sort.Strings(locs)
	locSet := make(map[string]struct{}, n)
	for _, l := range locs {
		if !utf8.ValidString(l) {
			return nil, nil, ruleErrorf("地点标识不是合法 UTF-8: %q", l)
		}
		if l == "" {
			return nil, nil, ruleErrorf("地点标识不能为空")
		}
		if _, ok := locSet[l]; ok {
			return nil, nil, ruleErrorf("地点标识重复: %q", l)
		}
		locSet[l] = struct{}{}
	}

	// 必有与禁用道路各自去重（反向列出算同一条），并校验端点。
	reqSet := make(map[Edge]struct{}, len(required))
	for _, e := range required {
		if err := checkMapEdge(e, locSet, "必有道路"); err != nil {
			return nil, nil, err
		}
		reqSet[canonicalEdge(e)] = struct{}{}
	}
	banSet := make(map[Edge]struct{}, len(banned))
	for _, e := range banned {
		if err := checkMapEdge(e, locSet, "禁用道路"); err != nil {
			return nil, nil, err
		}
		banSet[canonicalEdge(e)] = struct{}{}
	}
	for e := range reqSet {
		if _, ok := banSet[e]; ok {
			return nil, nil, ruleErrorf("道路 %q-%q 不能同时必有和禁用", e.From, e.To)
		}
	}

	if roadCount < 0 {
		return nil, nil, ruleErrorf("目标道路数量不能为负: %d", roadCount)
	}
	if roadCount < len(reqSet) {
		return nil, nil, ruleErrorf("目标道路数量 %d 小于必有道路数量 %d", roadCount, len(reqSet))
	}

	// 候选道路：全部地点两两组合中未被禁用的道路，按规范次序排列。
	candidates := make([]Edge, 0, n*(n-1)/2)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			e := Edge{From: locs[i], To: locs[j]}
			if _, ok := banSet[e]; !ok {
				candidates = append(candidates, e)
			}
		}
	}
	if roadCount > len(candidates) {
		return nil, nil, ruleErrorf("目标道路数量 %d 超过可用道路数量 %d", roadCount, len(candidates))
	}

	index := make(map[string]int, n)
	for i, l := range locs {
		index[l] = i
	}

	// 必有道路先并入并查集；连通全图最少还需要 (分量数-1) 条道路。
	uf := newUnionFind(n)
	components := n
	for e := range reqSet {
		if uf.union(index[e.From], index[e.To]) {
			components--
		}
	}
	if minNeeded := len(reqSet) + components - 1; roadCount < minNeeded {
		return nil, nil, ruleErrorf("目标道路数量 %d 少于连通全图所需数量 %d", roadCount, minNeeded)
	}

	// 禁用道路不得使地图无法连通：全部候选道路必须能连成一片。
	{
		full := newUnionFind(n)
		c := n
		for _, e := range candidates {
			if full.union(index[e.From], index[e.To]) {
				c--
			}
		}
		if c > 1 {
			return nil, nil, ruleErrorf("禁用道路使地图无法连通")
		}
	}

	// 待选道路（候选中除去必有）按规范次序洗牌，洗牌只取决于种子与
	// 约束内容，因此结果与输入次序、重复及正反写法无关。
	pool := make([]Edge, 0, len(candidates)-len(reqSet))
	for _, e := range candidates {
		if _, ok := reqSet[e]; !ok {
			pool = append(pool, e)
		}
	}
	rnd := mapRand{state: uint64(seed)}
	for i := len(pool) - 1; i > 0; i-- {
		j := int(rnd.next() % uint64(i+1))
		pool[i], pool[j] = pool[j], pool[i]
	}

	// 先沿洗牌次序连通全图，连通后继续按次序补足目标数量。连通阶段
	// 因端点已属同一分量而跳过的道路记入 skipped：它们仍是合法道路，
	// 目标数量接近可用道路总数时需要靠它们补足，不能像洗牌耗尽一样
	// 误判为无解（种子只决定选哪张合法地图，不决定请求能否成功）。
	chosen := make([]Edge, 0, roadCount)
	for e := range reqSet {
		chosen = append(chosen, e)
	}
	skipped := make([]Edge, 0)
	for _, e := range pool {
		if len(chosen) == roadCount {
			break
		}
		if components > 1 {
			if uf.union(index[e.From], index[e.To]) {
				components--
				chosen = append(chosen, e)
			} else {
				skipped = append(skipped, e)
			}
		} else {
			chosen = append(chosen, e)
		}
	}
	if len(chosen) < roadCount {
		// 走到这里说明连通全图之前 pool 已耗尽（仅在洗牌次序使关键
		// 连通边排得靠后、而目标数量又需要几乎全部道路时发生）。补做
		// 一轮 Kruskal：按洗牌次序加入能合并分量的跳过道路；连通后
		// 剩余名额按洗牌次序由跳过道路补足。可行性检查已保证这些道路
		// 足以连通全图，且跳过道路总数足以补足目标数量。
		extraNeeded := roadCount - len(chosen)
		for _, e := range skipped {
			if extraNeeded == 0 {
				break
			}
			if components > 1 {
				if uf.union(index[e.From], index[e.To]) {
					components--
					chosen = append(chosen, e)
					extraNeeded--
				}
			} else {
				chosen = append(chosen, e)
				extraNeeded--
			}
		}
	}
	if len(chosen) != roadCount || components > 1 {
		// 前面的可行性检查已保证有解时不会走到这里。
		return nil, nil, ruleErrorf("无法生成 %d 条道路的连通地图", roadCount)
	}
	sort.Slice(chosen, func(i, j int) bool {
		if chosen[i].From != chosen[j].From {
			return chosen[i].From < chosen[j].From
		}
		return chosen[i].To < chosen[j].To
	})
	return locs, chosen, nil
}

// checkMapEdge 校验一条必有或禁用道路的端点：必须引用已有地点，
// 且不能连接同一地点。
func checkMapEdge(e Edge, locSet map[string]struct{}, what string) error {
	if _, ok := locSet[e.From]; !ok {
		return ruleErrorf("%s引用了不存在的地点: %q", what, e.From)
	}
	if _, ok := locSet[e.To]; !ok {
		return ruleErrorf("%s引用了不存在的地点: %q", what, e.To)
	}
	if e.From == e.To {
		return ruleErrorf("%s不能连接同一地点: %q", what, e.From)
	}
	return nil
}

// unionFind 是生成地图时用于连通性判断的并查集。
type unionFind struct {
	parent []int
}

func newUnionFind(n int) *unionFind {
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	return &unionFind{parent: parent}
}

func (u *unionFind) find(x int) int {
	for u.parent[x] != x {
		u.parent[x] = u.parent[u.parent[x]]
		x = u.parent[x]
	}
	return x
}

// union 合并两个元素所在集合，原本不在同一集合时返回 true。
func (u *unionFind) union(a, b int) bool {
	ra, rb := u.find(a), u.find(b)
	if ra == rb {
		return false
	}
	u.parent[ra] = rb
	return true
}

// mapRand 是地图生成使用的确定性伪随机源（splitmix64），只由种子决定，
// 不依赖任何全局状态，因此同一种子在任何进程中都得到同一序列。
type mapRand struct {
	state uint64
}

func (r *mapRand) next() uint64 {
	r.state += 0x9E3779B97F4A7C15
	z := r.state
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

package world

import (
	"fmt"
	"math"
)

// NameMapping 描述旧规则中一个名称到新规则名称的显式转换关系。
//
// From 必须是来源记录旧规则中存在的地点或物品种类，To 必须是目标规则中
// 存在的对应名称；空名称、来源不存在于旧规则或目标不存在于新规则都在
// 预览时返回规则错误。
type NameMapping struct {
	// From 是旧规则中的地点或物品种类名称。
	From string
	// To 是新规则中的对应名称。
	To string
}

// MigrationPreview 是把槽当前最新记录按对应关系显式迁移到目标规则的
// 预览结果。
//
// 预览只读：返回所依据的来源记录标识、旧新版本、按对应关系转换后的完整
// 世界状态（深拷贝）以及是否可提交。它不改变槽指向、历史或任何记录文件；
// 修改返回的状态也不影响存档。
type MigrationPreview struct {
	// RecordID 是所依据的来源记录标识（槽当前最新记录）。
	RecordID RecordID
	// OldVersion 是来源记录的规则版本。
	OldVersion string
	// TargetVersion 是目标规则版本。
	TargetVersion string
	// State 是转换后的完整世界状态（深拷贝），规则已替换为目标规则。
	// 正式迁移以排他锁下重新读取和计算的结果为准，不使用调用方可能改过
	// 的本状态。
	State State
	// Committable 表示转换后的状态能否在目标规则下提交（无阻碍）。
	Committable bool
	// Blockers 是全部阻碍，排序与升级检查一致；重复预览输出顺序一致。
	Blockers []Blocker
}

// MigrationResult 是正式迁移的返回结果。
type MigrationResult struct {
	// Preview 是对来源记录与目标规则的预览结果（排他锁下重新读取并计算）。
	Preview MigrationPreview
	// Record 是成功时新记录的元信息；被阻碍时为零值。
	Record RecordInfo
}

// validateMappings 校验转换对应关系：来源必须存在于旧规则，目标必须存在
// 于新规则，名称非空，同一来源不重复指定。即使没有角色使用这些名称也要
// 检查。
func validateMappings(old, target Rules, locations, items []NameMapping) error {
	oldLocs := make(map[string]struct{}, len(old.Locations))
	for _, l := range old.Locations {
		oldLocs[l] = struct{}{}
	}
	newLocs := make(map[string]struct{}, len(target.Locations))
	for _, l := range target.Locations {
		newLocs[l] = struct{}{}
	}
	if err := validateMappingSet("地点", locations, oldLocs, newLocs); err != nil {
		return err
	}

	oldKinds := make(map[string]struct{}, len(old.ItemKinds))
	for _, k := range old.ItemKinds {
		oldKinds[k] = struct{}{}
	}
	newKinds := make(map[string]struct{}, len(target.ItemKinds))
	for _, k := range target.ItemKinds {
		newKinds[k] = struct{}{}
	}
	return validateMappingSet("物品种类", items, oldKinds, newKinds)
}

func validateMappingSet(kind string, mappings []NameMapping, oldNames, newNames map[string]struct{}) error {
	seen := make(map[string]struct{}, len(mappings))
	for i, m := range mappings {
		if m.From == "" {
			return ruleErrorf("%s转换关系 %d 的来源名称为空", kind, i)
		}
		if m.To == "" {
			return ruleErrorf("%s转换关系 %d 的目标名称为空", kind, i)
		}
		if _, ok := oldNames[m.From]; !ok {
			return ruleErrorf("%s转换关系的来源 %q 不存在于旧规则", kind, m.From)
		}
		if _, ok := newNames[m.To]; !ok {
			return ruleErrorf("%s转换关系的目标 %q 不存在于新规则", kind, m.To)
		}
		if _, dup := seen[m.From]; dup {
			return ruleErrorf("%s转换关系的来源 %q 重复指定", kind, m.From)
		}
		seen[m.From] = struct{}{}
	}
	return nil
}

// applyMigration 按对应关系转换状态：角色按对应关系改变所在地点（无需
// 符合旧道路），物品改变种类但不增减数量；多个条目转换成同一种物品时
// 合并数量，按原列表中首次出现的位置保留一个条目。转换只作用于原始名称
// 一次，不沿对应关系连续替换，因此互换名称也有确定结果。未指定的名称
// 保持原样。种子、时间片、角色标识及角色排列保持不变。
//
// 合并数量或携带总量超出 int 范围时返回规则错误，不回绕也不丢弃物品。
func applyMigration(st State, locations, items []NameMapping) (State, error) {
	locLookup := make(map[string]string, len(locations))
	for _, m := range locations {
		locLookup[m.From] = m.To
	}
	itemLookup := make(map[string]string, len(items))
	for _, m := range items {
		itemLookup[m.From] = m.To
	}

	out := cloneState(st)

	for i := range out.Characters {
		if to, ok := locLookup[out.Characters[i].Location]; ok {
			out.Characters[i].Location = to
		}
	}

	for i := range out.Characters {
		ch := &out.Characters[i]
		merged := make([]CharacterItem, 0, len(ch.Items))
		indexByName := make(map[string]int, len(ch.Items))
		for _, it := range ch.Items {
			name := it.Item
			if to, ok := itemLookup[name]; ok {
				name = to
			}
			if idx, ok := indexByName[name]; ok {
				sum, ok := addInt(merged[idx].Count, it.Count)
				if !ok {
					return State{}, ruleErrorf("角色 %q 的物品 %q 合并数量超出整数范围", ch.ID, name)
				}
				merged[idx].Count = sum
			} else {
				indexByName[name] = len(merged)
				merged = append(merged, CharacterItem{Item: name, Count: it.Count})
			}
		}
		ch.Items = merged

		// 携带总量溢出检查：各物品数量都合法，但不同物品相加可能超出
		// int 范围，同样不能回绕或丢弃。这是显式迁移特有的整数范围门槛，
		// 与携带上限判断不同：无论目标规则是否给该角色设置上限，真实总量
		// 超出 int 范围都拒绝，不能因为共用总量判断而把“无上限”当成允许
		// 溢出迁移。精确求和与其余入口共用 carryTotal，此处只保留自己的
		// 溢出判定。
		if carryTotal(ch.Items).Cmp(maxIntBig) > 0 {
			return State{}, ruleErrorf("角色 %q 携带总量超出整数范围", ch.ID)
		}
	}
	return out, nil
}

// addInt 做一次带溢出检查的 int 加法，返回结果与是否溢出。
func addInt(a, b int) (int, bool) {
	if b > 0 && a > math.MaxInt-b {
		return 0, false
	}
	if b < 0 && a < math.MinInt-b {
		return 0, false
	}
	return a + b, true
}

// migrationComputeLocked 在调用方已持锁（共享或排他均可）的前提下读取并
// 校验槽当前最新记录，校验转换对应关系，计算转换后的状态与阻碍。来源
// 读取、完整性检查、可接受版本与版本相异判断共用
// sourceForTransformLocked，本函数只负责迁移自己的对应关系校验、转换与
// 阻碍计算。不写入。
func (a *Archive) migrationComputeLocked(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, *envelope, error) {
	latest, env, err := a.sourceForTransformLocked(slot, acceptedVersions, target.Version)
	if err != nil {
		return MigrationPreview{}, nil, err
	}
	if err := validateMappings(env.State.Rules, target, locations, items); err != nil {
		return MigrationPreview{}, nil, err
	}
	transformed, err := applyMigration(env.State, locations, items)
	if err != nil {
		return MigrationPreview{}, nil, err
	}
	// 转换后的状态保存目标规则。
	transformed.Rules = cloneRules(target)
	blockers := checkCompatibility(transformed, target)
	preview := MigrationPreview{
		RecordID:      latest,
		OldVersion:    env.State.Rules.Version,
		TargetVersion: target.Version,
		State:         transformed,
		Committable:   len(blockers) == 0,
		Blockers:      blockers,
	}
	return preview, env, nil
}

// PreviewMigration 预览把槽当前最新记录按对应关系显式迁移到目标规则。
//
// 传入槽名、可接受的旧版本集合、目标规则，以及旧地点到新地点、旧物品到
// 新物品的对应关系，返回所依据的来源记录标识、旧新版本、转换后的完整
// 世界状态（深拷贝）及是否可提交。转换只作用于原始名称一次，不沿对应
// 关系连续替换；未指定的名称保持原样。转换后仍有缺失地点、不被允许的
// 物品或超过目标携带上限时，一次列出全部阻碍，重复预览输出顺序一致。
//
// 预览只读：不改变世界、历史或槽当前记录，修改返回的状态也不影响存档。
// 目标规则须满足规则自身的合法性要求且版本与来源不同；对应关系的来源
// 必须存在于旧规则、目标必须存在于新规则（即使没有角色使用也要检查），
// 空目标或未知名称返回规则错误；合并数量或携带总量超出 int 范围返回规则
// 错误。来源缺失、损坏或版本不被接受时沿用已有对应错误，不自动挑选历史
// 记录。
func (a *Archive) PreviewMigration(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, error) {
	if !validSlotName(slot) {
		return MigrationPreview{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return MigrationPreview{}, err
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return MigrationPreview{}, err
	}
	defer lock.release()
	preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
	if err != nil {
		return MigrationPreview{}, err
	}
	return preview, nil
}

// Migrate 在预览后正式迁移：用目标规则与转换后的状态生成一条以来源为父
// 的新记录并加入本槽保存次序。
//
// 传入与预览相同的条件，并带预览返回的来源记录标识 source。提交时在
// 排他锁下重新读取并完整校验来源，重新校验目标规则与对应关系、重新计算
// 转换后的状态与阻碍，绝不使用调用方可能改过的预览状态：
//
//   - source 为空，或槽已不再指向该来源（被并发覆盖、升级、确认恢复或
//     另一次迁移抢先提交），返回 *ConflictError。
//   - 来源缺失、损坏或版本不被接受分别返回已有的不存在、损坏或版本拒绝
//     错误，不改选其他记录。
//   - 仍有阻碍时返回阻碍信息并拒绝保存，不改变当前记录或历史。
//
// 成功后产生一条以来源为父的新记录，保存目标规则与转换后的状态，加入
// 本槽保存次序；种子、时间片、角色标识及角色排列保持原样。与覆盖、升级、
// 确认恢复或另一次迁移竞争时，同一来源最多一个成功。任何拒绝都不改变
// 当前记录或历史；中断后重开只能看到迁移前或迁移后的完整记录与历史。
// 旧记录及已有分支保留原状态，恢复读取仍能找到旧版本；迁移后的记录可
// 继续按新规则移动、改变物品并保存，普通读取不自动转换。
func (a *Archive) Migrate(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping, source RecordID) (MigrationResult, error) {
	if !validSlotName(slot) {
		return MigrationResult{}, &NotFoundError{Slot: slot}
	}
	if source == "" {
		return MigrationResult{}, &ConflictError{Slot: slot, Reason: "迁移必须提供所依据的来源记录标识"}
	}
	if err := validateRules(target); err != nil {
		return MigrationResult{}, err
	}
	lock, err := acquireLock(a.dir)
	if err != nil {
		return MigrationResult{}, err
	}
	defer lock.release()

	oldPointer, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return MigrationResult{}, err
	}
	// 乐观并发控制：槽必须仍指向预览时的来源记录。
	if oldPointer.Latest != source {
		return MigrationResult{}, &ConflictError{
			Slot:   slot,
			Reason: "所依据的来源记录已不是该槽最新记录",
		}
	}

	// 排他锁下重新读取、校验并计算，不采信调用方带回的任何状态。
	preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
	if err != nil {
		return MigrationResult{}, err
	}
	if !preview.Committable {
		return MigrationResult{Preview: preview}, &RuleError{
			Reason: fmt.Sprintf("迁移被阻碍: 转换后的状态无法在目标规则下提交（%d 处阻碍）", len(preview.Blockers)),
		}
	}

	// 保存目标规则与排他锁下重新计算出的转换结果；以来源为父，沿用
	// 共同的新记录组装、落盘与槽指针提交路径。记录完整落盘后才原子
	// 更新指针：新记录前置进保存次序，旧历史原样保留。崩溃在这一步
	// 之前时槽保持迁移前的指向与历史，新记录因不在历史索引中而不会
	// 进入恢复候选。
	info, err := a.appendSlotRecordLocked(slotSave{
		slot:          slot,
		oldPointer:    oldPointer,
		parent:        source,
		historyAnchor: source,
		state:         preview.State,
	})
	if err != nil {
		return MigrationResult{}, err
	}
	return MigrationResult{Preview: preview, Record: info}, nil
}

