// unicodeRules 用中文、表情符号和真实存在的替换字符“�”命名全部文本
// 标识，包括没有现存角色的携带上限键。它们都是合法 UTF-8，应按普通
// 标识接受，仍需满足非空、唯一、引用等原有条件。
func unicodeRules() Rules {
	return Rules{
		Version:   "规则一😀/v�",
		Locations: []string{"大厅", "院子", "洞穴"},
		Edges: []Edge{
