}

func unicodeState() State {
	return State{
		Seed:  2026,
		Rules: unicodeRules(),
		Time:  4,
		Characters: []Character{
			{ID: "英雄", Location: "大厅", Items: []CharacterItem{
				{Item: "金币", Count: 1},
				{Item: "钥匙🗝", Count: 1},
			}},
			{ID: "法师🧙", Location: "院子", Items: []CharacterItem{
				{Item: "金币", Count: 2},
			}},
