		Seed:       3,
		Rules:      baseRules(),
		Time:       2,
		Characters: []Character{{ID: "hero", Location: "hall"}},
	}
	st.Rules.ItemKinds = append(st.Rules.ItemKinds, invalidB)
	w, err := WorldFromState(st)
	if w != nil {
		t.Fatalf("非法状态不应重建出世界: %+v", w)
	}
