			t.Fatal("非法物品种类应被拒绝")
		} else {
			assertInvalidRuleError(t, err, "物品种类")
		}
	})
	t.Run("无现存角色的携带上限键", func(t *testing.T) {
		req := good()
		req.CarryLimits = map[string]int{invalidA: 4}
		if _, err := GenerateWorld(req); err == nil {
			t.Fatal("非法携带上限键应被拒绝")
