		req.Characters = []Character{{ID: invalidA, Location: "hall"}}
		if _, err := GenerateWorld(req); err == nil {
			t.Fatal("非法角色标识应被拒绝")
		} else {
			assertInvalidRuleError(t, err, "角色")
		}
	})
}

